import { useEffect, useState } from "react";
import type { Weapon } from "../calculator/calculator.ts";

/**
 * The affinity IDs (-1 for unique weapons) each weapon can be buffed in, generated by
 * scripts/build_buffable_data.py
 */
export type Buffable = Record<string, number[]>;

export function isBuffable(buffable: Buffable, { weaponName, affinityId }: Weapon) {
  return buffable[weaponName]?.includes(affinityId) ?? false;
}

let buffablePromise: Promise<Buffable> | undefined;

/**
 * Loads which weapons can be buffed
 */
export default function useBuffable() {
  const [buffable, setBuffable] = useState<Buffable>({});
  useEffect(() => {
    buffablePromise ??= fetch("/buffable.json").then((res) => res.json());
    buffablePromise.then(setBuffable).catch(() => setBuffable({}));
  }, []);
  return buffable;
}
